const { simpleParser } = require('mailparser');

// El .eml llega del Webhook como binario en la propiedad "data".
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const correo = await simpleParser(buffer);

const autenticacion = correo.headers.get('authentication-results');

return [{
  json: {
    message_id: correo.messageId ?? null,
    remitente: correo.from?.value?.[0]?.address?.toLowerCase() ?? null,
    asunto: correo.subject ?? null,
    autenticacion: Array.isArray(autenticacion) ? autenticacion.join('; ') : (autenticacion ?? null),
    hora_recepcion: correo.date ? correo.date.toISOString() : null,
    texto: correo.text ?? '',
  },
}];

