const respuesta = $input.first().json;

// Busca la respuesta del modelo por su tipo: antes puede venir un "thought" (el razonamiento).
const salida = (respuesta.steps ?? []).find(s => s.type === 'model_output');
const texto = salida?.content?.find(c => c.type === 'text')?.text;
if (!texto) {
  throw new Error('Gemini no devolvió un model_output con texto');
}

let extraccion;
try {
  extraccion = JSON.parse(texto);
} catch (e) {
  throw new Error('La respuesta de Gemini no es JSON válido: ' + e.message);
}

const uso = respuesta.usage ?? {};

return [{
  json: {
    caso: $('Registrar correo').first().json.caso,
    extraccion,
    modelo: respuesta.model,
    prompt_version: 'corte-vertical-provisional',
    configuracion: 'solo_ia',
    tokens_entrada: uso.total_input_tokens ?? null,
    // El razonamiento también se factura como salida: se suma para que el coste por correo sea real.
    tokens_salida: (uso.total_output_tokens ?? 0) + (uso.total_thought_tokens ?? 0),
  },
}];

